<?php

/* @autogenerated */
declare(strict_types=1);

use Civi\Lughauth\Features\Access\UserAcceptedTermnsOfUse\Domain\ValueObject\Accessor\UserAcceptedTermnsOfUseUserAgentAccessor;
use PHPUnit\Framework\TestCase;

/**
 * Unit tests for the UserAcceptedTermnsOfUseUserAgentAccessor trait.
 *
 * Covers null default, string/VO assignment via withUserAgent,
 * getUserAgent/userAgent accessors, and isUserAgentChanged with/without original.
 */
class UserAcceptedTermnsOfUseUserAgentAccessorUnitTest extends TestCase
{
    /**
     * Asserts that withUserAgent creates a new instance with the UserAgent set
     * from a string value, and getUserAgent returns the primitive string.
     */
    public function testWithUserAgentFromString(): void
    {
        // Arrange
        $holder = new ImplWithUserAcceptedTermnsOfUseUserAgentAccessorUnitTest();

        // Act
        $result = $holder->withUserAgent('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->getUserAgent());
    }
    /**
     * Asserts that withuserAgent has access to the value object
     * from a string value, and getUserAgent returns the primitive string.
     */
    public function testWithUserAgentFromValueObject(): void
    {
        // Arrange
        $holder = new ImplWithUserAcceptedTermnsOfUseUserAgentAccessorUnitTest();

        // Act
        $result = $holder->withUserAgent('one');

        // Assert
        $this->assertNotSame($holder, $result);
        $this->assertEquals('one', $result->userAgent()->value());
    }
    public function testChangedUserAgent(): void
    {
        // Arrange
        $holder = new ImplWithUserAcceptedTermnsOfUseUserAgentAccessorUnitTest();
        $original = $holder->withUserAgent('one');
        $same = $holder->withUserAgent('one');
        $modified = $holder->withUserAgent('other');

        // Act
        $unchanged = $holder->isUserAgentChanged();
        $withSame = $original->isUserAgentChanged($same);
        $withDiferent = $original->isUserAgentChanged($modified);

        // Assert
        $this->assertFalse($unchanged);
        $this->assertFalse($withSame);
        $this->assertTrue($withDiferent);
    }
}
class ImplWithUserAcceptedTermnsOfUseUserAgentAccessorUnitTest
{
    use UserAcceptedTermnsOfUseUserAgentAccessor;
}
